mapper.select:
SELECT id, workspace_id, knowledge_base_id, user_id, title, created_at, updated_at
FROM chat_sessions
WHERE id = #{id}
  AND workspace_id = #{workspaceId}
  AND knowledge_base_id = #{knowledgeBaseId}
  AND user_id = #{userId}

mapper.insert:
INSERT INTO chat_messages (
	id, workspace_id, session_id, turn_id, role, status, content
) VALUES (
	#{id}, #{workspaceId}, #{sessionId}, #{turnId}, #{role}, #{status}, #{content}
)

INSERT INTO message_citations (
	id, workspace_id, message_id, ordinal, chunk_id, document_id,
	document_version_id, document_name, sequence_number, source_position,
	excerpt, similarity
) VALUES (
	#{id}, #{workspaceId}, #{messageId}, #{citation.index}, #{citation.chunkId},
	#{citation.documentId}, #{citation.documentVersionId}, #{citation.documentName},
	#{citation.sequenceNumber}, CAST(#{citation.sourcePosition} AS jsonb),
	#{citation.excerpt}, #{citation.similarity}
)
